events, contexts = [], []

def doc(key, name, url, date, ident, locator, primary=True, lang='ja', kind='library', typ='legal_publication'):
    repo = source('JP', key, name, url, lang, publisher=repository_for(url), kind=kind, accessed_on='2026-11-17', notes='Прочитано: '+locator+'. Первичность относится к оригинальному тексту документа, не к современным аннотациям или AI要約. Сканы и цитаты не распространяются.')
    return evidence(repo, name, ident, date, lang, typ if primary else 'historical_study', locator, primary=primary, locator=locator)

def add(ev, slug, date, ru, en, text, english, category, sensitive=False):
    row = event('JP', slug, date, 'jp', ru, en, text, english, ev, category=category, scope='national', sensitive=sensitive)
    if not ev['is_primary']:
        row['confidence'] = 'medium'
    events.append(row)
    return row

def ctx(ev, slug, first, last, kind, ru, en, text, english, statistics=None):
    contexts.append(context('JP', slug, 'jp', first, last, kind, ru, en, text, english, ev, statistics))

